/**
 * loadDisplaySubjectArea against the extension host's golden output.
 *
 * The golden files (test/fixtures/golden) are generated by the repo-root test
 * test/unit/displayDomainGolden.test.ts, which drives the real extension host
 * over the same fixture projects. This proves the one-call core pipeline
 * builds the same DisplaySubjectArea the extension posts to its webview — minus
 * the editor-only `templates`, `manifestModels` and `existingModels` — and
 * fails bad domains with the same messages.
 *
 * Domain paths are passed relative to each fixture project, the way a host
 * reading from a repository would name them, so the golden messages are
 * compared with their `<root>/` prefix removed.
 */

import { describe, it, expect } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';

import { loadDisplaySubjectArea } from '../../src/loadDisplayDomain';
import { SubjectAreaFileError, SubjectAreaValidationError } from '../../src/domain';
import { normaliseForStorageEquivalence, normaliseStorageRows, type StorageEquivalenceRow } from '../../src/storageEquivalence';
import { dbmlStorageReader } from '../../src/dbml/index';

const FIXTURES = path.resolve(__dirname, '../fixtures');
const GOLDEN_DIR = path.join(FIXTURES, 'golden');

const SUBJECT_AREA_CASES: Record<string, string> = {
  showcase: '.erd-studio/silver/showcase.json',
  'v4-inline': '.erd-studio/bronze/orders.json',
  'missing-model': '.erd-studio/silver/partial.json',
  'no-layers': '.erd-studio/gold/accounts.json',
  'missing-positions': '.erd-studio/silver/showcase.json',
  'library-relationships': '.erd-studio/gold/sales.json',
  'v4-nameless-column': '.erd-studio/silver/orders.json',
  'composite-and-self': '.erd-studio/gold/vault.json',
  'data-type-alias': '.erd-studio/silver/orders.json',
  'domain-one-to-many': '.erd-studio/gold/sales.json',
  'duplicate-key': '.erd-studio/silver/orders.json',
};

const ERROR_CASES: Record<string, string> = {
  legacy: '.erd-studio/silver/legacy.json',
  hybrid: '.erd-studio/silver/hybrid.json',
  future: '.erd-studio/silver/future.json',
  noversion: '.erd-studio/silver/noversion.json',
  array: '.erd-studio/silver/array.json',
  empty: '.erd-studio/silver/empty.json',
  invalid: '.erd-studio/silver/invalid.json',
  badlayer: '.erd-studio/platinum/badlayer.json',
  // Native DBML storage (S2): a DBML diagram that does not parse, one from a
  // newer schema, one with git conflict markers, and a table file passed as
  // the diagram. Read with the DBML readers.
  'dbml-syntax': '.erd-studio/silver/dbml-syntax.dbml',
  'dbml-future': '.erd-studio/silver/dbml-future.dbml',
  'dbml-conflict': '.erd-studio/silver/dbml-conflict.dbml',
  'dbml-not-a-diagram': '.erd-studio/tables/dim_customer.dbml',
};

/**
 * The DBML twins (packages/core/test/fixtures/dbml/<case>): the same projects
 * stored as native DBML. Each draws what its YAML case's golden draws once
 * both go through **only the §2.8 rows it lists** (§9.2: a row a case does
 * not list must not change that case), and each listed row is needed (drop
 * it and the two differ). The full comparator (D24) agrees as well.
 *
 * These compare the Display shape. Rows that touch only the Unified shape
 * (composite-and-self's lone `fk_lonely` key and raw Ref spellings, the
 * library-relationships domain copy) show there, with the host, in S4.
 */
const DBML_TWIN_CASES: Record<string, { domainPath: string; rows: Partial<Record<StorageEquivalenceRow, string>> }> = {
  showcase: {
    domainPath: '.erd-studio/silver/showcase.dbml',
    rows: {
      relationshipOrder: 'the diagram file held the relationships in its own order; a relationships file keeps its Refs sorted',
      emptyAnnotations: 'the JSON file holds "annotations": []; a diagram with no Note blocks reads back with no list',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
    },
  },
  'composite-and-self': {
    domainPath: '.erd-studio/gold/vault.dbml',
    rows: {
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
    },
  },
  'missing-positions': {
    domainPath: '.erd-studio/silver/showcase.dbml',
    rows: {
      relationshipOrder: 'the diagram file held the relationships in its own order; a relationships file keeps its Refs sorted',
      emptyAnnotations: 'the JSON file holds "annotations": []; a diagram with no Note blocks reads back with no list',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
    },
  },
  'missing-model': {
    domainPath: '.erd-studio/silver/partial.dbml',
    rows: { schemaVersion: 'the YAML case is 5, a DBML diagram is 7' },
  },
  'library-relationships': {
    domainPath: '.erd-studio/gold/sales.dbml',
    rows: {
      oneToMany: 'a library one-to-many (1.6.6 / 1.6.7) is stored canonically, as fct_order many-to-one',
      schemaVersion: 'the YAML case is 5, a DBML diagram is 7',
    },
  },
};

/**
 * What a twin cannot hold, beyond the §2.8 rows, applied to the YAML golden
 * before the comparison, each with its one-line reason.
 */
const DBML_TWIN_EXCEPTIONS: Record<string, (expected: Record<string, unknown>) => void> = {
  // A Ref is drawn only from a readable DBML owner (§2.4): dim_missing has no
  // file and broken.dbml does not parse, so the diagram file's two
  // relationships from them have no DBML home; and broken's load error is a
  // DBML one (kind, line and code), not YAML's.
  'missing-model': (expected) => {
    expected.relationships = [];
    const models = expected.models as Array<Record<string, unknown>>;
    const broken = models.find((m) => m.name === 'broken')!;
    broken.loadError = { kind: 'dbmlSyntax', line: 5, code: '1005' };
  },
};

const LINE_COLUMN = / \(line \d+ column \d+\)/g;

function readGolden(file: string): { type: string; payload: Record<string, unknown> } {
  return JSON.parse(fs.readFileSync(path.join(GOLDEN_DIR, file), 'utf-8'));
}

/** A readFile over one fixture project: relative paths, ENOENT as null. */
function fsReadFile(root: string) {
  return async (p: string): Promise<string | null> => {
    try {
      return fs.readFileSync(path.join(root, p), 'utf-8');
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  };
}

describe('loadDisplaySubjectArea matches the extension host golden output', () => {
  describe.each(Object.entries(SUBJECT_AREA_CASES))('%s', (name, domainPath) => {
    it('builds the posted DisplaySubjectArea, without the editor-only fields', async () => {
      const root = path.join(FIXTURES, name);
      const domain = await loadDisplaySubjectArea({
        domainPath,
        readFile: fsReadFile(root),
        readOnly: false,
        warn: () => {},
      });

      const expected = { ...readGolden(`${name}.host.json`).payload };
      delete expected.templates;
      delete expected.manifestModels;
      delete expected.existingModels;

      // postMessage serialises the payload, which drops undefined values.
      expect(JSON.parse(JSON.stringify(domain))).toEqual(expected);
    });
  });

  describe.each(Object.entries(ERROR_CASES))('errors/%s', (name, domainPath) => {
    it('rejects with the golden message and the matching error class', async () => {
      const golden = readGolden(`errors.${name}.host.json`).payload as {
        message: string; kind?: string; fileProblem?: 'empty' | 'syntax'; line?: number; column?: number;
      };
      const isDbml = domainPath.endsWith('.dbml');
      let caught: unknown;
      try {
        await loadDisplaySubjectArea({
          domainPath,
          readFile: fsReadFile(path.join(FIXTURES, 'errors')),
          readOnly: false,
          warn: () => {},
          ...(isDbml ? { dbml: dbmlStorageReader } : {}),
        });
      } catch (err) {
        caught = err;
      }
      // The host tags SubjectAreaFileError failures with kind 'domain-file'.
      expect(caught).toBeInstanceOf(golden.kind === 'domain-file' ? SubjectAreaFileError : SubjectAreaValidationError);
      // An empty or invalid file (#186): the host words its own sentence from
      // core's reason and location, so those are what must agree.
      if (golden.fileProblem) {
        const err = caught as SubjectAreaFileError;
        expect(err.reason).toBe(golden.fileProblem === 'empty' ? 'empty' : isDbml ? 'invalid-dbml' : 'invalid-json');
        expect({ line: err.line, column: err.column }).toEqual({ line: golden.line, column: golden.column });
        return;
      }
      const message = (caught as Error).message.replace(LINE_COLUMN, '');
      expect(message).toBe(golden.message.split('<root>/').join(''));
    });
  });

  describe.each(Object.entries(DBML_TWIN_CASES))('the DBML twin of %s', (name, { domainPath, rows }) => {
    const listed = Object.keys(rows) as StorageEquivalenceRow[];
    const read = async (): Promise<{ twin: Record<string, unknown>; expected: Record<string, unknown> }> => {
      const domain = await loadDisplaySubjectArea({
        domainPath,
        readFile: fsReadFile(path.join(FIXTURES, 'dbml', name)),
        readOnly: false,
        warn: () => {},
        dbml: dbmlStorageReader,
      });
      expect(domain.schemaVersion).toBe(7);
      const expected = { ...readGolden(`${name}.host.json`).payload };
      delete expected.templates;
      delete expected.manifestModels;
      delete expected.existingModels;
      DBML_TWIN_EXCEPTIONS[name]?.(expected);
      return { twin: JSON.parse(JSON.stringify(domain)), expected };
    };

    it(`draws what the YAML golden draws through only its listed §2.8 rows (${listed.join(', ')})`, async () => {
      const { twin, expected } = await read();
      expect(normaliseStorageRows(twin, listed)).toEqual(normaliseStorageRows(expected, listed));
      expect(normaliseForStorageEquivalence(twin)).toEqual(normaliseForStorageEquivalence(expected));
    });

    it.each(listed)('needs the row it lists: %s', async (row) => {
      const { twin, expected } = await read();
      const without = listed.filter((r) => r !== row);
      expect(normaliseStorageRows(twin, without)).not.toEqual(normaliseStorageRows(expected, without));
    });
  });
});
